import { describe, expect, it } from "vitest";
import { applyThreshold, FALLBACK_ACTION, UNKNOWN_INTENT } from "../lib/threshold";
import fixture from "./fixtures/threshold_cases.json";

// The fixture is generated by demo/backend/generate_threshold_cases.py from the backend's decision function
// (which wraps the project's sole_intent.rejection rules) using the real model's probabilities.
// The backend test suite verifies the fixture is current.

describe("applyThreshold matches the backend decision function", () => {
  it(`agrees on all ${fixture.cases.length} generated cases`, () => {
    expect(fixture.cases.length).toBeGreaterThan(300);
    for (const c of fixture.cases) {
      const d = applyThreshold(c.probabilities, c.threshold, fixture.class_order);
      const got = {
        raw_prediction: d.raw_prediction,
        confidence: d.confidence,
        final_intent: d.final_intent,
        status: d.status,
        fallback_applied: d.fallback_applied,
        action: d.application.action,
      };
      expect(got, c.name).toEqual(c.expected);
    }
  });

  it("covers exact boundary cases (equal accepted, +1ulp rejected)", () => {
    const equal = fixture.cases.filter((c) => c.name.endsWith("(equal)"));
    const above = fixture.cases.filter((c) => c.name.endsWith("+ 1ulp"));
    expect(equal.length).toBeGreaterThan(0);
    for (const c of equal) expect(applyThreshold(c.probabilities, c.threshold, fixture.class_order).fallback_applied).toBe(false);
    for (const c of above) expect(applyThreshold(c.probabilities, c.threshold, fixture.class_order).final_intent).toBe(UNKNOWN_INTENT);
  });
});

describe("applyThreshold rules", () => {
  const order = ["A", "B", "HELP_SUPPORT"];

  it("supports the full 0–100% range", () => {
    const p = { A: 0.5, B: 0.3, HELP_SUPPORT: 0.2 };
    expect(applyThreshold(p, 0, order).final_intent).toBe("A");
    expect(applyThreshold(p, 0.5, order).final_intent).toBe("A");
    expect(applyThreshold(p, 0.51, order).final_intent).toBe(UNKNOWN_INTENT);
    expect(applyThreshold(p, 1, order).final_intent).toBe(UNKNOWN_INTENT);
  });

  it("keeps HELP_SUPPORT predictions separate from the fallback", () => {
    const d = applyThreshold({ A: 0.1, B: 0.2, HELP_SUPPORT: 0.7 }, 0.5, order);
    expect(d.final_intent).toBe("HELP_SUPPORT");
    expect(d.fallback_applied).toBe(false);
    expect(d.application.action).toBe("ROUTE_HELP_SUPPORT");
    const f = applyThreshold({ A: 0.4, B: 0.35, HELP_SUPPORT: 0.25 }, 0.5, order);
    expect(f.final_intent).toBe(UNKNOWN_INTENT);
    expect(f.application.action).toBe(FALLBACK_ACTION);
    expect(f.application.offers).toContain("HELP_SUPPORT");
    expect(f.application.suggested_intent).toBe("A");
  });

  it("does not modify the probabilities", () => {
    const p = { A: 0.6, B: 0.3, HELP_SUPPORT: 0.1 };
    const copy = { ...p };
    for (let t = 0; t <= 100; t++) applyThreshold(p, t / 100, order);
    expect(p).toEqual(copy);
  });

  it("rejects invalid input", () => {
    expect(() => applyThreshold({ A: 1, B: 0, HELP_SUPPORT: 0 }, 1.01, order)).toThrow();
    expect(() => applyThreshold({ A: 1, B: 0, HELP_SUPPORT: 0 }, Number.NaN, order)).toThrow();
    expect(() => applyThreshold({ A: 1 }, 0.5, order)).toThrow();
  });
});
